/// <summary>
/// PaffH 21.07.25
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXEndMonthClosing, FormButtonCreateNewBatchJobCSRefreshSalesAlliance), FormControlEventType::Clicked)]
public static void FormButtonCreateNewBatchJobCSRefreshSalesAlliance_OnClicked(FormControl sender, FormControlEventArgs e)
{
    NDXUmsatzParametersGlobal parameter = NDXUmsatzParametersGlobal::find(true);
    if (parameter.BatchHeaderRefRecIdPrepareSalesAlliance &&
        Box::yesNo("@NDX:NDXBatchJobAssignementExistsIgnore", DialogButton::No) == DialogButton::No)
    {
        return;
    }

    Args args = new Args();
    NDXBatchJobUmsatzCSRefreshAllianceSalesGroup batchJob = NDXBatchJobUmsatzCSRefreshAllianceSalesGroup::construct();
    RefRecId refRecId = batchJob.addTask(args);
    ttsbegin;
    parameter.BatchHeaderRefRecIdPrepareSalesAlliance = refRecId;
    parameter.update();
    ttscommit;

}
